{
  "name": "opencode-proxies",
  "version": "1.0.0",
  "description": "OpenCode v2 plugin for routing model HTTP requests through configurable forward proxies.",
  "type": "module",
  "main": "dist/index.js",
  "types": "index.d.ts",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "license": "MIT",
  "engines": {
    "node": ">=24"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ysm-dev/opencode-proxies.git"
  },
  "bugs": {
    "url": "https://github.com/ysm-dev/opencode-proxies/issues"
  },
  "homepage": "https://github.com/ysm-dev/opencode-proxies#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "proxy",
    "warp"
  ],
  "files": [
    "dist",
    "index.d.ts",
    "LICENSE",
    "README.md"
  ],
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "scripts": {
    "build": "bun build src/index.ts --outfile dist/index.js --target node --format esm --packages external",
    "typecheck": "tsgo --noEmit",
    "format": "biome format --write .",
    "format:check": "biome format .",
    "lint": "biome lint --write .",
    "lint:check": "biome lint .",
    "knip": "knip",
    "check": "biome check --write .",
    "check:ci": "biome check .",
    "test": "bun test",
    "test:coverage": "bun test --coverage",
    "test:package": "node scripts/package-smoke.mjs",
    "prepare": "bun run build",
    "prepack": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.3",
    "undici": "8.10.2"
  },
  "devDependencies": {
    "@biomejs/biome": "2.4.12",
    "@types/node": "^24.12.2",
    "@typescript/native-preview": "beta",
    "bun-types": "^1.4.0",
    "knip": "^6.14.1"
  }
}
